// Count subarrays with sum k
int countK(vector<int>& a, int k) {
    unordered_map<long long, int> cnt{{0, 1}};
    long long s = 0; int ans = 0;
    for (int x : a) { s += x; if (cnt.count(s - k)) ans += cnt[s - k]; cnt[s]++; }
    return ans;
}

