        std::vector<bool> visited(n, false);
        std::vector<std::vector<std::string>> res;
        for (int i = 0; i < n; i++) {
            if (visited[i]) continue;
            std::vector<std::string> group = {strs[i]};
            visited[i] = true;
            for (int j = i + 1; j < n; j++) {
                if (!visited[j] && isAnagram(strs[i], strs[j])) {
                    visited[j] = true;
                    group.push_back(strs[j]);
                }
            }
            res.push_back(group);
        }
        return res;
    }
};

