        tokens = data.split(",")
        ptr = 0
        def decode() -> Optional[TreeNode]:
            nonlocal ptr
            if ptr >= len(tokens):
                return None
            val = tokens[ptr]
            ptr += 1
            if val == "#":
                return None
            node = TreeNode(int(val))
            node.left = decode()
            node.right = decode()
            return node
        return decode()

