class Solution:
    def kthSmallest(self, root: Optional[TreeNode], k: int) -> int:
        st: list = []
        cur = root
        while cur or st:
            while cur:
                st.append(cur)
                cur = cur.left
            cur = st.pop()
            k -= 1
            if k == 0:
                return cur.val
            cur = cur.right
        return -1

