def two_sum_sorted(a, target):
    l, r = 0, len(a) - 1
    while l < r:
        s = a[l] + a[r]
        if s == target:
            return l, r
        if s < target:
            l += 1                 # need a bigger sum: only moving l helps
        else:
            r -= 1                 # need a smaller sum: only moving r helps
    return None
